// This file contains utils copied from the app-shell

export class Random {
  private static A = 5182453;
  private static C = 1013904223;
  private static M = Number.MAX_SAFE_INTEGER;

  private seed: number;

  // eslint-disable-next-line require-jsdoc
  constructor(seed: number) {
    this.seed = Math.abs(seed);
  }

  next = () => {
    this.seed = (Random.A * this.seed + Random.C) % Random.M;
    return this.seed / Random.M;
  };
}

interface Point {
  x: number;
  y: number;
}

export const getPoints = (
  vector: number[],
  radius: number,
  cx: number,
  cy: number,
) => {
  const points: Point[] = [];
  points.push({ x: -cx, y: -cy });
  for (let i = 0; i < vector.length; i++) {
    const a = ((i / (vector.length - 1)) * Math.PI) / 2;
    const r = vector[i] * radius + 0.25 * radius;
    const x = Math.cos(a) * r - cx;
    const y = Math.sin(a) * r - cy;
    points.push({ x, y });
  }
  return points;
};

export const path = (
  points: Point[],
  command: (point: Point, i: number, points: Point[]) => string,
) => {
  return [...points, points[0]].reduce(
    (d, point, i, a) =>
      i === 0 ? `M ${point.x},${point.y}` : `${d} ${command(point, i, a)}`,
    '',
  );
};

const smoothing = 0.2;

const line = (pointA: Point, pointB: Point) => {
  const lengthX = pointB.x - pointA.x;
  const lengthY = pointB.y - pointA.y;
  return {
    length: Math.sqrt(Math.pow(lengthX, 2) + Math.pow(lengthY, 2)),
    angle: Math.atan2(lengthY, lengthX),
  };
};

const controlPoint = (
  current: Point,
  previous: Point,
  next: Point,
  reverse: boolean,
): Point => {
  const p = previous || current;
  const n = next || current;

  const o = line(p, n);

  const angle = o.angle + (reverse ? Math.PI : 0);
  const length = o.length * smoothing;

  const x = current.x + Math.cos(angle) * length;
  const y = current.y + Math.sin(angle) * length;
  return { x, y };
};

export const bezierCommand = (point: Point, i: number, a: Point[]) => {
  const cps = controlPoint(a[i - 1], a[i - 2], point, false);

  const cpe = controlPoint(point, a[i - 1], a[i + 1], true);
  return `C ${cps.x},${cps.y} ${cpe.x},${cpe.y} ${point.x},${point.y}`;
};

export const getColors = (h: number, s: number) => {
  return [`hsl(${h}, ${s}%, 50%)`, `hsl(${h}, ${s}%, 15%)`];
};

export const getAbbr = (name: string) => {
  const last = name.split('.').pop();
  return (last?.[0]?.toUpperCase() ?? '?') + (last?.[1] ?? '?');
};

export const generateVector = (count: number, random: Random) => {
  const vector: number[] = [];
  for (let i = 0; i < count; i++) {
    vector.push(random.next());
  }
  return vector;
};

export const hash = (str: string) => {
  let hash = 0;
  if (str.length === 0) {
    return hash;
  }
  for (let i = 0; i < str.length; i++) {
    const char = str.charCodeAt(i);
    hash = (hash << 5) - hash + char;
    hash |= 0;
  }
  return hash;
};
